import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as n,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse(`{"title":"Simon Willison's Agentic Engineering Patterns 深度解析","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/prompt/agentic-engineering-patterns.md","filePath":"zh/tech/prompt/agentic-engineering-patterns.md","lastUpdated":1786817277000}`),o={name:"zh/tech/prompt/agentic-engineering-patterns.md"};function s(l,t,r,g,h,p){return n(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="simon-willison-s-agentic-engineering-patterns-深度解析" tabindex="-1">Simon Willison&#39;s Agentic Engineering Patterns 深度解析 <a class="header-anchor" href="#simon-willison-s-agentic-engineering-patterns-深度解析" aria-label="Permalink to &quot;Simon Willison&#39;s Agentic Engineering Patterns 深度解析&quot;">​</a></h1><blockquote><p>来源：<a href="https://simonwillison.net/guides/agentic-engineering-patterns/" target="_blank" rel="noreferrer">Simon Willison - Agentic Engineering Patterns</a> 作者：Simon Willison（著名技术博主，Datasette 作者） 整理时间：2026-04-12</p></blockquote><h2 id="前言-为什么这篇文章值得细读" tabindex="-1">前言：为什么这篇文章值得细读 <a class="header-anchor" href="#前言-为什么这篇文章值得细读" aria-label="Permalink to &quot;前言：为什么这篇文章值得细读&quot;">​</a></h2><p>Simon Willison 是我长期关注的技术作家。他的文章有一个鲜明特点：<strong>不是告诉你&quot;怎么做&quot;，而是帮你理解&quot;为什么这样做&quot;</strong>。</p><p>Agentic Engineering Patterns 这套指南于 2026 年 2 月开始连载，是目前关于 AI Coding 实践最系统、最有深度的免费资源之一。与其他泛泛而谈的&quot;AI 编程指南&quot;不同，Willison 本人就是 Claude Code、OpenAI Codex 等工具的深度用户，他的每一个 pattern 都来自真实项目的第一手经验。</p><p><strong>这篇文档的目标</strong>：不是翻译或摘要，而是以第一性原理的视角，深度解析每个 pattern 背后的工程思维，以及它们如何重塑我们对&quot;软件工程&quot;这件事的理解。**</p><h2 id="一、重新定义-agentic-engineering" tabindex="-1">一、重新定义&quot;Agentic Engineering&quot; <a class="header-anchor" href="#一、重新定义-agentic-engineering" aria-label="Permalink to &quot;一、重新定义&quot;Agentic Engineering&quot;&quot;">​</a></h2><h3 id="_1-1-什么是-coding-agent" tabindex="-1">1.1 什么是 Coding Agent <a class="header-anchor" href="#_1-1-什么是-coding-agent" aria-label="Permalink to &quot;1.1 什么是 Coding Agent&quot;">​</a></h3><p>Willison 给出了一个极简但精准的定义：</p><blockquote><p><strong>Agents run tools in a loop to achieve a goal</strong></p></blockquote><p>这句话拆解开来，每个词都精确：</p><ul><li><strong>Tools</strong>：Agent 拥有可调用的工具（不只是 LLM 输出文本）</li><li><strong>Loop</strong>：反复执行，直到目标达成</li><li><strong>Goal</strong>：有明确的目标导向</li><li><strong>Agents</strong>：不是&quot;助手&quot;，是能自主决策的软件系统</li></ul><p>关键区分在于&quot;code execution&quot;——Coding Agent 能<strong>执行代码</strong>，这让它与普通 LLM 对话有本质区别。LLM 输出代码，只是文本；Coding Agent 输出代码，并运行它、验证它、迭代它。</p><h3 id="_1-2-agentic-engineering-不是什么" tabindex="-1">1.2 &quot;Agentic Engineering&quot; 不是什么 <a class="header-anchor" href="#_1-2-agentic-engineering-不是什么" aria-label="Permalink to &quot;1.2 &quot;Agentic Engineering&quot; 不是什么&quot;">​</a></h3><p>Willison 专门用一节区分了 <strong>Agentic Engineering</strong> 和 <strong>Vibe Coding</strong>：</p><table tabindex="0"><thead><tr><th>概念</th><th>定义</th><th>本质</th></tr></thead><tbody><tr><td><strong>Vibe Coding</strong></td><td>&quot;让 LLM 写代码，同时你忘记代码的存在&quot;</td><td>放弃理解，把代码当黑箱</td></tr><tr><td><strong>Agentic Engineering</strong></td><td>用 coding agent 辅助开发，但人始终是质量把控者</td><td>人机协作，工程化实践</td></tr></tbody></table><p>这是对 Andrej Karpathy &quot;Vibe Coding&quot; 概念的有力回应：Vibe Coding 作为<strong>原型探索</strong>是合理的，但它不等同于&quot;用 AI 写代码&quot;的全部。</p><p><strong>关键洞察</strong>：Coding Agent 降低的是&quot;<strong>打字成本</strong>&quot;，而不是&quot;<strong>软件工程的认知成本</strong>&quot;。理解代码、设计架构、评估取舍——这些仍然是人的核心职责。</p><h2 id="二、第一性原理-代码变便宜了-然后呢" tabindex="-1">二、第一性原理：代码变便宜了，然后呢？ <a class="header-anchor" href="#二、第一性原理-代码变便宜了-然后呢" aria-label="Permalink to &quot;二、第一性原理：代码变便宜了，然后呢？&quot;">​</a></h2><h3 id="_2-1-一个被低估的认知转变" tabindex="-1">2.1 一个被低估的认知转变 <a class="header-anchor" href="#_2-1-一个被低估的认知转变" aria-label="Permalink to &quot;2.1 一个被低估的认知转变&quot;">​</a></h3><p>Willison 在 &quot;Writing code is cheap now&quot; 中指出：</p><blockquote><p>Coding agents dramatically drop the cost of typing code into the computer, which disrupts so many of our existing personal and organizational intuitions about which trade-offs make sense.</p></blockquote><p>这是全文最核心的一句话。它揭示了一个深刻的事实：<strong>我们大量工程习惯是建立在&quot;代码昂贵&quot;这个隐含假设上的</strong>。</p><h3 id="_2-2-这些习惯需要被颠覆" tabindex="-1">2.2 这些习惯需要被颠覆 <a class="header-anchor" href="#_2-2-这些习惯需要被颠覆" aria-label="Permalink to &quot;2.2 这些习惯需要被颠覆&quot;">​</a></h3><p>当代码成本趋近于零，以下旧习惯需要重新审视：</p><p><strong>宏观层面</strong>：</p><ul><li>&quot;这个功能值不值得开发&quot;——现在可以用 agent 快速验证后再决定</li><li>&quot;不要过度设计&quot;——如果过度设计的成本也趋近于零呢？</li><li>&quot;先规划，再编码&quot;——规划阶段的探索性编码现在几乎免费</li></ul><p><strong>微观层面</strong>：</p><ul><li>&quot;这个函数要不要重构成更优雅的写法&quot;——现在可以让 agent 在后台异步完成</li><li>&quot;这个边界情况要不要写测试&quot;——agent 写测试几乎零成本</li><li>&quot;这段代码要不要加注释&quot;——agent 可以自动生成文档</li></ul><h3 id="_2-3-好代码仍然有成本" tabindex="-1">2.3 &quot;好代码仍然有成本&quot; <a class="header-anchor" href="#_2-3-好代码仍然有成本" aria-label="Permalink to &quot;2.3 &quot;好代码仍然有成本&quot;&quot;">​</a></h3><p>Willison 没有陷入&quot;代码免费 = 代码不重要&quot;的误区。他明确指出：<strong>交付代码 ≠ 交付好代码</strong>。</p><p>好代码的标准：</p><ul><li>代码能工作（works）</li><li><strong>我们知道</strong>代码能工作（we know it works）——通过验证，而非假设</li><li>解决了正确的问题</li><li>处理错误情况优雅且可预测</li><li>简单且最小化</li><li>有测试保护</li><li>有文档且文档反映当前状态</li><li>设计支持未来变更</li></ul><p><strong>核心张力</strong>：交付新代码的成本几乎为零，但交付&quot;好代码&quot;的成本依然显著。Agent 可以帮你写代码，但<strong>质量的责任仍在你</strong>。</p><h2 id="三、核心工程模式" tabindex="-1">三、核心工程模式 <a class="header-anchor" href="#三、核心工程模式" aria-label="Permalink to &quot;三、核心工程模式&quot;">​</a></h2><h3 id="_3-1-hoard-everything——知识囤积策略" tabindex="-1">3.1 Hoard Everything——知识囤积策略 <a class="header-anchor" href="#_3-1-hoard-everything——知识囤积策略" aria-label="Permalink to &quot;3.1 Hoard Everything——知识囤积策略&quot;">​</a></h3><p>Willison 最独特的洞见之一：<strong>构建软件的技能很大程度上取决于你知道什么是可能的、以及如何实现</strong>。</p><p>这听起来朴素，细想极其深刻——工程师的价值不在于能从零发明算法，而在于&quot;见过足够多的解决方案&quot;。当你见过足够多，你就能在新问题出现时快速识别&quot;这个问题像上次遇到的 X，可以用 Y 方案解决&quot;。</p><h4 id="_3-1-1-囤积的正确姿势" tabindex="-1">3.1.1 囤积的正确姿势 <a class="header-anchor" href="#_3-1-1-囤积的正确姿势" aria-label="Permalink to &quot;3.1.1 囤积的正确姿势&quot;">​</a></h4><p>不是收藏文章链接，而是<strong>带可执行证据的解决方案</strong>：</p><ul><li><strong>Blog + TIL（Today I Learned）</strong>：记录&quot;如何做到某件事&quot;的笔记</li><li><strong>GitHub 仓库</strong>：收集代码片段，特别是小型概念验证（proof-of-concept）</li><li><strong>工具集合</strong>：单 HTML 文件解决特定问题的工具库</li><li><strong>研究仓库</strong>：更大的研究项目，包含代码和详细报告</li></ul><h4 id="_3-1-2-为什么这对-coding-agent-特别有价值" tabindex="-1">3.1.2 为什么这对 Coding Agent 特别有价值 <a class="header-anchor" href="#_3-1-2-为什么这对-coding-agent-特别有价值" aria-label="Permalink to &quot;3.1.2 为什么这对 Coding Agent 特别有价值&quot;">​</a></h4><p>最有力的例子：Willison 用两个已有代码片段（PDF.js + Tesseract.js），通过一个 prompt 生成了一个浏览器端 OCR 工具。他没有从零学习两个库的 API，而是直接告诉 agent：&quot;把这两个组合起来&quot;。</p><p><strong>关键洞见</strong>：Coding Agent 意味着我们<strong>只需要想出一个有用的技巧一次</strong>。如果这个技巧被记录在某处（有代码示例），我们的 agent 以后可以查阅并用于解决任何类似问题。</p><h4 id="_3-1-3-重组-recombination-的力量" tabindex="-1">3.1.3 重组（Recombination）的力量 <a class="header-anchor" href="#_3-1-3-重组-recombination-的力量" aria-label="Permalink to &quot;3.1.3 重组（Recombination）的力量&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>新问题 + 已知解决方案 A + 已知解决方案 B → 新工具</span></span></code></pre></div><p>这是工程创造力的本质，不是发明，而是<strong>组合</strong>。</p><h3 id="_3-2-compound-engineering-loop——复利工程循环" tabindex="-1">3.2 Compound Engineering Loop——复利工程循环 <a class="header-anchor" href="#_3-2-compound-engineering-loop——复利工程循环" aria-label="Permalink to &quot;3.2 Compound Engineering Loop——复利工程循环&quot;">​</a></h3><p>Every 公司的 Dan Shipper 和 Kieran Klaassen 提出&quot;Compound Engineering&quot;概念，被 Willison 采纳：</p><blockquote><p>每个编码项目完成后，进行复盘（retrospective），将经验文档化供未来 agent 使用。</p></blockquote><p>这个循环的精妙之处：</p><ul><li><strong>短期</strong>：每次任务学到的经验被积累</li><li><strong>长期</strong>：agent 的提示词和工具配置不断改进</li><li><strong>复利效应</strong>：每次改进都让下一次更好</li></ul><p><strong>类比</strong>：就像 TDD 每次测试覆盖保护未来重构，Compound Engineering 每次复盘都在改进未来 agent 的表现。</p><h3 id="_3-3-异步-agent——后台并行工作流" tabindex="-1">3.3 异步 Agent——后台并行工作流 <a class="header-anchor" href="#_3-3-异步-agent——后台并行工作流" aria-label="Permalink to &quot;3.3 异步 Agent——后台并行工作流&quot;">​</a></h3><p>Willison 大量使用异步 coding agent（Gemini Jules、OpenAI Codex web、Claude Code on the web）在后台处理重构任务，而他在本地继续其他工作。</p><p>这彻底改变了工程工作的组织方式：</p><ul><li>一个 agent 在后台做 API 重构</li><li>另一个在做测试覆盖</li><li>人在做需要深度思考的设计决策</li><li>最终在 PR 中评估 agent 的产出</li></ul><p><strong>关键变化</strong>：从&quot;人按顺序做 A、B、C&quot;，变成&quot;人指挥多个 agent 并行做 A、B、C&quot;。</p><h2 id="四、反模式——agentic-engineering-中绝对要避免的事" tabindex="-1">四、反模式——Agentic Engineering 中绝对要避免的事 <a class="header-anchor" href="#四、反模式——agentic-engineering-中绝对要避免的事" aria-label="Permalink to &quot;四、反模式——Agentic Engineering 中绝对要避免的事&quot;">​</a></h2><h3 id="_4-1-不要向协作者强加未审查的代码" tabindex="-1">4.1 不要向协作者强加未审查的代码 <a class="header-anchor" href="#_4-1-不要向协作者强加未审查的代码" aria-label="Permalink to &quot;4.1 不要向协作者强加未审查的代码&quot;">​</a></h3><p>这是 Willison 最强调的反模式，措辞相当严厉：</p><blockquote><p>如果你开了一个 PR，里面有数百行（甚至数千行）agent 生成的代码，而你本人没有确保这些代码能工作——你是在把实际工作推给别人。他们本来也可以自己 prompt 一个 agent，你到底提供了什么价值？</p></blockquote><p>这句话击中了要害。当&quot;用 AI 写代码&quot;变得容易，最大的危险不是 AI 写得差，而是人<strong>放弃了本应承担的工程责任</strong>。</p><h3 id="_4-2-高质量-pr-的标准" tabindex="-1">4.2 高质量 PR 的标准 <a class="header-anchor" href="#_4-2-高质量-pr-的标准" aria-label="Permalink to &quot;4.2 高质量 PR 的标准&quot;">​</a></h3><p>一个合格的 agentic engineering PR 具有以下特征：</p><ol><li><strong>代码能工作</strong>，且你对此有信心（&quot;Your job is to deliver code that works&quot;）</li><li><strong>变更足够小</strong>，不会给审查者造成过大认知负担。几个小 PR 远好于一个大 PR</li><li><strong>包含额外上下文</strong>：更高层的目标是什么，为什么要做这个变更</li><li><strong>PR 描述也经过审查</strong>：agent 写的 PR 描述看起来很专业，但你仍然需要读它</li><li><strong>有手动测试的证据</strong>：截图、视频、或手动测试的笔记——证明你真的验证过</li></ol><p><strong>Willison 的建议</strong>：包含一些&quot;你确实做过工作&quot;的证据，比如手动测试记录、具体实现决策的注释，甚至是功能运行效果的截图和视频。</p><h2 id="五、coding-agent-内部原理——为什么理解它能帮你用得更好" tabindex="-1">五、Coding Agent 内部原理——为什么理解它能帮你用得更好 <a class="header-anchor" href="#五、coding-agent-内部原理——为什么理解它能帮你用得更好" aria-label="Permalink to &quot;五、Coding Agent 内部原理——为什么理解它能帮你用得更好&quot;">​</a></h2><h3 id="_5-1-llm-本质-token-预测机器" tabindex="-1">5.1 LLM 本质：Token 预测机器 <a class="header-anchor" href="#_5-1-llm-本质-token-预测机器" aria-label="Permalink to &quot;5.1 LLM 本质：Token 预测机器&quot;">​</a></h3><p>Willison 简洁地解释了 LLM 的工作原理：</p><ul><li>LLM 是<strong>根据概率预测下一个 token</strong> 的机器</li><li>输入是 token 序列，输出是 token 序列</li><li>&quot;thinking&quot; 或 &quot;reasoning&quot; 只是在生成更多 token 来&quot;推理&quot;，而不是真正的思考</li></ul><p>理解这一点非常重要，因为它解释了很多 LLM 的行为：</p><ul><li>为什么长上下文会让模型&quot;遗忘&quot;早期信息（注意力机制限制）</li><li>为什么&quot;说不要做什么&quot;不如&quot;说应该做什么&quot;有效</li><li>为什么示例（few-shot）比纯指令更有效</li></ul><h3 id="_5-2-chat-template——对话的本质" tabindex="-1">5.2 Chat Template——对话的本质 <a class="header-anchor" href="#_5-2-chat-template——对话的本质" aria-label="Permalink to &quot;5.2 Chat Template——对话的本质&quot;">​</a></h3><p>LLM 本质上是<strong>无状态的</strong>：每次调用都是从零开始。为了模拟对话，软件需要维护状态并<strong>在每次请求时重放整个对话历史</strong>。</p><p>这导致一个关键成本结构：</p><ul><li>对话越长，每条消息的输入 token 越多</li><li>Provider 按 token 数量收费</li><li>所以对话越长，<strong>每条消息的平均成本递增</strong></li></ul><h3 id="_5-3-token-caching——为什么-coding-agent-要避免修改早期对话" tabindex="-1">5.3 Token Caching——为什么 Coding Agent 要避免修改早期对话 <a class="header-anchor" href="#_5-3-token-caching——为什么-coding-agent-要避免修改早期对话" aria-label="Permalink to &quot;5.3 Token Caching——为什么 Coding Agent 要避免修改早期对话&quot;">​</a></h3><p>大多数模型 provider 对缓存的输入 token 提供折扣价。Coding Agent 被设计为<strong>尽量不修改早期对话内容</strong>，以最大化缓存命中率。</p><p>这解释了为什么好的 coding agent session 习惯很重要：</p><ul><li>保持指令简洁且不频繁改动</li><li>将大量信息放在 system prompt 中（只加载一次）</li><li>在 session 中渐进式增加上下文，而非来回修改</li></ul><h3 id="_5-4-tool-calling-的机制" tabindex="-1">5.4 Tool Calling 的机制 <a class="header-anchor" href="#_5-4-tool-calling-的机制" aria-label="Permalink to &quot;5.4 Tool Calling 的机制&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LLM 输出特殊格式文本（如 &lt;tool&gt;get_weather(&quot;SF&quot;)&lt;/tool&gt;）</span></span>
<span class="line"><span>  → Agent Harness 用正则提取函数调用</span></span>
<span class="line"><span>  → 执行工具</span></span>
<span class="line"><span>  → 将结果注入对话</span></span>
<span class="line"><span>  → LLM 继续处理</span></span></code></pre></div><p>Coding Agent 的核心是<strong>工具循环</strong>。最强大的工具是能执行代码的工具（Bash、Python 等），因为这让 agent 能够验证自己的输出。</p><h3 id="_5-5-system-prompt——agent-行为的源头" tabindex="-1">5.5 System Prompt——Agent 行为的源头 <a class="header-anchor" href="#_5-5-system-prompt——agent-行为的源头" aria-label="Permalink to &quot;5.5 System Prompt——Agent 行为的源头&quot;">​</a></h3><p>System prompt 是给 LLM 的指令集，告诉它&quot;如何行为&quot;。好的 coding agent system prompt 可能数百行，包含：</p><ul><li>工具定义和使用规范</li><li>代码风格指南</li><li>工作流程建议</li><li>限制和边界条件</li></ul><p>Willison 指出：<a href="https://github.com/openai/codex/blob/rust-v0.114.0/codex-rs/core/templates/model_instructions/gpt-5.2-codex_instructions_template.md" target="_blank" rel="noreferrer">OpenAI Codex 的 system prompt</a> 是一个很好的参考。</p><h3 id="_5-6-reasoning——-思考-token-的作用" tabindex="-1">5.6 Reasoning——&quot;思考&quot; token 的作用 <a class="header-anchor" href="#_5-6-reasoning——-思考-token-的作用" aria-label="Permalink to &quot;5.6 Reasoning——&quot;思考&quot; token 的作用&quot;">​</a></h3><p>2025 年的一个重大进展是&quot;推理&quot;能力的引入。模型在回答问题之前先生成&quot;思考 token&quot;来推演，这类似于人类&quot;出声思考&quot;。</p><p>关键理解：</p><ul><li>推理占用 token，但提高了复杂问题的质量</li><li>对调试特别有价值：模型可以在推理阶段跟踪代码调用链，找到问题根源</li><li>很多 coding agent 支持调节推理强度（花更多或更少时间&quot;思考&quot;）</li></ul><h2 id="六、git——被低估的-agentic-engineering-工具" tabindex="-1">六、Git——被低估的 Agentic Engineering 工具 <a class="header-anchor" href="#六、git——被低估的-agentic-engineering-工具" aria-label="Permalink to &quot;六、Git——被低估的 Agentic Engineering 工具&quot;">​</a></h2><h3 id="_6-1-git-重新成为第一公民" tabindex="-1">6.1 Git 重新成为第一公民 <a class="header-anchor" href="#_6-1-git-重新成为第一公民" aria-label="Permalink to &quot;6.1 Git 重新成为第一公民&quot;">​</a></h3><p>Willison 认为 Git 对 agentic engineering 的价值被大大低估：</p><blockquote><p>Git 仓库的完整历史在你自己的机器上。历史挖掘几乎零成本。</p></blockquote><p>当 agent 可以访问你的 Git 历史，它可以在几秒内：</p><ul><li>了解项目结构和技术栈</li><li>理解最近的变更方向</li><li>找到类似问题的历史解决方案</li></ul><h3 id="_6-2-高效-prompt-库" tabindex="-1">6.2 高效 prompt 库 <a class="header-anchor" href="#_6-2-高效-prompt-库" aria-label="Permalink to &quot;6.2 高效 prompt 库&quot;">​</a></h3><p>Willison 分享了一系列让 agent 善用 Git 的 prompt：</p><table tabindex="0"><thead><tr><th>场景</th><th>Prompt</th></tr></thead><tbody><tr><td>让 agent 了解项目</td><td><code>Run the tests</code></td></tr><tr><td>查看最近的变更</td><td><code>What have been the recent changes?</code></td></tr><tr><td>理解 merge 策略</td><td><code>Tell me about the different ways to merge in git</code></td></tr><tr><td>修复 merge 冲突</td><td><code>I messed up my git repo - help me fix it</code></td></tr><tr><td>使用 bisect</td><td><code>Help me bisect this - I think a bug was introduced recently</code></td></tr></tbody></table><h3 id="_6-3-重写历史——从负担到工具" tabindex="-1">6.3 重写历史——从负担到工具 <a class="header-anchor" href="#_6-3-重写历史——从负担到工具" aria-label="Permalink to &quot;6.3 重写历史——从负担到工具&quot;">​</a></h3><p>传统观点认为 Git 历史应该&quot;如实记录&quot;。Willison 提出了更激进的观点：</p><blockquote><p>不要把 Git 历史看成&quot;实际发生了什么&quot;的永久记录，而是把它看成软件项目演进的<strong>刻意讲述的故事</strong>。</p></blockquote><p>这在 agentic engineering 中特别有意义，因为：</p><ul><li>Agent 可以帮助重组提交，使历史更清晰</li><li>Agent 写的 commit message 通常比人写的更好</li><li>可以从旧仓库提取代码创建新仓库，同时保留关键历史</li></ul><h3 id="_6-4-git-bisect——从-陡峭学习曲线-到-随时可用" tabindex="-1">6.4 Git Bisect——从&quot;陡峭学习曲线&quot;到&quot;随时可用&quot; <a class="header-anchor" href="#_6-4-git-bisect——从-陡峭学习曲线-到-随时可用" aria-label="Permalink to &quot;6.4 Git Bisect——从&quot;陡峭学习曲线&quot;到&quot;随时可用&quot;&quot;">​</a></h3><p>Git bisect 是一个强大的二分查找工具，但传统上需要一个可执行的测试条件，这让很多开发者望而却步。</p><p>有了 coding agent：你只需要说&quot;我怀疑最近有个 commit 引入了这个 bug&quot;，agent 会帮你：</p><ul><li>构造合适的测试条件</li><li>执行 bisect</li><li>解读结果</li></ul><p>从&quot;偶一用之的工具&quot;升级为&quot;任何时候都可以用的调试手段&quot;。</p><h2 id="七、subagent——管理-context-限制的策略" tabindex="-1">七、Subagent——管理 Context 限制的策略 <a class="header-anchor" href="#七、subagent——管理-context-限制的策略" aria-label="Permalink to &quot;七、Subagent——管理 Context 限制的策略&quot;">​</a></h2><h3 id="_7-1-context-窗口的物理限制" tabindex="-1">7.1 Context 窗口的物理限制 <a class="header-anchor" href="#_7-1-context-窗口的物理限制" aria-label="Permalink to &quot;7.1 Context 窗口的物理限制&quot;">​</a></h3><p>LLM 的 context 窗口（一次能处理的 token 数量）虽有提升，但相比 AI 能力的发展速度仍然有限。顶级模型一般在 100 万 token 左右，但最佳质量通常在 20 万 token 以下。</p><h3 id="_7-2-subagent-的本质" tabindex="-1">7.2 Subagent 的本质 <a class="header-anchor" href="#_7-2-subagent-的本质" aria-label="Permalink to &quot;7.2 Subagent 的本质&quot;">​</a></h3><p>Subagent 是 coding agent 的&quot;分身&quot;——当一个任务太大时，主 agent 派生出新的 agent 实例来处理子任务，这个新实例拥有全新的 context 窗口。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主 Agent context 即将耗尽</span></span>
<span class="line"><span>  → 派生出 Subagent，给予新 context</span></span>
<span class="line"><span>  → Subagent 完成子任务，返回结果</span></span>
<span class="line"><span>  → 主 Agent 整合结果，继续工作</span></span></code></pre></div><h3 id="_7-3-subagent-的三种类型" tabindex="-1">7.3 Subagent 的三种类型 <a class="header-anchor" href="#_7-3-subagent-的三种类型" aria-label="Permalink to &quot;7.3 Subagent 的三种类型&quot;">​</a></h3><ol><li><strong>Explore Subagent</strong>：主 agent 在处理任务前先派它探索代码库结构</li><li><strong>Parallel Subagent</strong>：同时运行多个 subagent 处理相互独立的任务（加速）</li><li><strong>Specialist Subagent</strong>：带有自定义 system prompt 或工具的专业化 subagent</li></ol><h3 id="_7-4-specialist-subagent-的实际应用" tabindex="-1">7.4 Specialist Subagent 的实际应用 <a class="header-anchor" href="#_7-4-specialist-subagent-的实际应用" aria-label="Permalink to &quot;7.4 Specialist Subagent 的实际应用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角色</th><th>功能</th><th>价值</th></tr></thead><tbody><tr><td>Code Reviewer</td><td>审查代码找 bug 和设计问题</td><td>隐藏详细测试输出，减少主 agent 认知负担</td></tr><tr><td>Test Runner</td><td>运行大型测试套件并报告结果</td><td>避免冗长测试输出淹没主 context</td></tr><tr><td>Debugger</td><td>专门调试问题，深挖代码路径</td><td>可以在自己的 context 中详细探索</td></tr><tr><td>Researcher</td><td>调研某个技术问题并返回报告</td><td>保持主 session 干净</td></tr></tbody></table><p><strong>Willison 的忠告</strong>：subagent 很有价值，但不要过度拆分。主 agent 完全有能力调试或审查自己的输出，只要它有足够的 token。</p><h2 id="八、测试——agentic-engineering-的基石" tabindex="-1">八、测试——Agentic Engineering 的基石 <a class="header-anchor" href="#八、测试——agentic-engineering-的基石" aria-label="Permalink to &quot;八、测试——Agentic Engineering 的基石&quot;">​</a></h2><h3 id="_8-1-测试为什么不再是-奢侈品" tabindex="-1">8.1 测试为什么不再是&quot;奢侈品&quot; <a class="header-anchor" href="#_8-1-测试为什么不再是-奢侈品" aria-label="Permalink to &quot;8.1 测试为什么不再是&quot;奢侈品&quot;&quot;">​</a></h3><p>Willison 的核心论点：</p><blockquote><p>旧的&quot;不写测试&quot;的借口——太耗时、太贵、在快速迭代时频繁重写——在 agent 可以几分钟内搞定测试的情况下，不再成立。</p></blockquote><p>这是一个范式转变：</p><ul><li><strong>以前</strong>：测试是投资，需要认真考虑投入产出比</li><li><strong>现在</strong>：测试是默认行为，成本可忽略</li></ul><h3 id="_8-2-first-run-the-tests-——四词工程纪律" tabindex="-1">8.2 &quot;First, run the tests&quot;——四词工程纪律 <a class="header-anchor" href="#_8-2-first-run-the-tests-——四词工程纪律" aria-label="Permalink to &quot;8.2 &quot;First, run the tests&quot;——四词工程纪律&quot;">​</a></h3><p>Willison 发现&quot;When I start a new session with an agent against an existing project&quot;时，最好的开场 prompt 是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>First, run the tests</span></span></code></pre></div><p>对于 Python 项目（使用 uv）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uv run test</span></span></code></pre></div><p>这四（或三）个词的 prompt 实际上涵盖了大量工程纪律：</p><ul><li>告诉 agent 有测试套件存在</li><li>迫使 agent 学会如何运行测试</li><li>大概率确保 agent 未来会运行测试来验证自己的改动</li><li>让 agent 了解项目的复杂度和规模</li></ul><h3 id="_8-3-红-绿-tdd——简洁提示的巨大威力" tabindex="-1">8.3 红/绿 TDD——简洁提示的巨大威力 <a class="header-anchor" href="#_8-3-红-绿-tdd——简洁提示的巨大威力" aria-label="Permalink to &quot;8.3 红/绿 TDD——简洁提示的巨大威力&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Use red/green TDD</span></span></code></pre></div><p>Willison 指出：每个好的模型都理解这句话的含义：&quot;使用测试驱动开发，先写测试，确认测试失败，再实现代码让测试通过&quot;。</p><p>这再次印证了 Willison 的核心哲学：<strong>模型已经内化了大量工程纪律，关键是你用简洁的提示激活它</strong>。</p><h3 id="_8-4-测试是理解代码库的最佳入口" tabindex="-1">8.4 测试是理解代码库的最佳入口 <a class="header-anchor" href="#_8-4-测试是理解代码库的最佳入口" aria-label="Permalink to &quot;8.4 测试是理解代码库的最佳入口&quot;">​</a></h3><p>当 coding agent 被问到某个功能的工作方式时，它的第一反应通常是<strong>找到并阅读相关测试</strong>。测试比代码更清晰地表达了&quot;这个功能应该做什么&quot;。</p><p>因此：</p><ul><li><strong>有测试的代码</strong> = agent 更容易理解、修改、扩展</li><li><strong>没测试的代码</strong> = agent 在修改时不知道是否破坏了现有功能</li></ul><h2 id="九、agentic-manual-testing——超越单元测试" tabindex="-1">九、Agentic Manual Testing——超越单元测试 <a class="header-anchor" href="#九、agentic-manual-testing——超越单元测试" aria-label="Permalink to &quot;九、Agentic Manual Testing——超越单元测试&quot;">​</a></h2><h3 id="_9-1-为什么手动测试仍然必要" tabindex="-1">9.1 为什么手动测试仍然必要 <a class="header-anchor" href="#_9-1-为什么手动测试仍然必要" aria-label="Permalink to &quot;9.1 为什么手动测试仍然必要&quot;">​</a></h3><blockquote><p>仅仅因为代码通过了测试，不代表代码按预期工作。</p></blockquote><p>这是非常重要的一点。测试覆盖的是&quot;你想到要测试的 case&quot;，而手动测试能发现<strong>你没想到的 case</strong>。</p><p>Willison 在 landing 任何功能前，一定要亲眼看到它正常工作。这不是不信任 agent，而是工程纪律。</p><h3 id="_9-2-agentic-manual-testing-的机制" tabindex="-1">9.2 Agentic Manual Testing 的机制 <a class="header-anchor" href="#_9-2-agentic-manual-testing-的机制" aria-label="Permalink to &quot;9.2 Agentic Manual Testing 的机制&quot;">​</a></h3><p>根据代码类型，有不同的测试方式：</p><p><strong>Python 库</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import mymodule; mymodule.test()&quot;</span></span></code></pre></div><p><strong>JSON API</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:5000/api/endpoint</span></span></code></pre></div><p><strong>Web UI</strong>：用 Playwright 或 Rodney（Willison 自己构建的 Chrome DevTools Protocol 封装）</p><h3 id="_9-3-showboat——记录-agent-工作痕迹的工具" tabindex="-1">9.3 Showboat——记录 agent 工作痕迹的工具 <a class="header-anchor" href="#_9-3-showboat——记录-agent-工作痕迹的工具" aria-label="Permalink to &quot;9.3 Showboat——记录 agent 工作痕迹的工具&quot;">​</a></h3><p>Willison 构建的 Showboat 是一个记录 agent 工作的工具：</p><ul><li><code>note</code>：追加 Markdown 笔记</li><li><code>exec</code>：执行命令并记录输入+输出</li><li><code>image</code>：添加截图</li></ul><p>最有价值的是 <code>exec</code>——它记录了&quot;agent 做了什么&quot;和&quot;结果是什么&quot;，防止 agent 写&quot;它希望发生过&quot;的结果。</p><p>这是对抗 agent 幻觉（hallucination）的有力工具。</p><h3 id="_9-4-rodney——让-agent-测试-web-ui" tabindex="-1">9.4 Rodney——让 Agent 测试 Web UI <a class="header-anchor" href="#_9-4-rodney——让-agent-测试-web-ui" aria-label="Permalink to &quot;9.4 Rodney——让 Agent 测试 Web UI&quot;">​</a></h3><p>Rodney 是一个基于 Chrome DevTools Protocol 的浏览器自动化工具，专为 coding agent 设计。它的特点：</p><ul><li>通过 <code>uvx rodney --help</code> 自动安装和使用</li><li>帮助输出包含 agent 需要的所有上下文</li><li>支持截图，让 agent 用自己的视觉能力评估页面外观</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 示例 prompt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Use</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uvx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rodney</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> explore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> page,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> take</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> screenshots</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> describe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> what</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> you</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> see.</span></span></code></pre></div><h2 id="十、linear-walkthroughs——将-经验-变成-理解" tabindex="-1">十、Linear Walkthroughs——将&quot;经验&quot;变成&quot;理解&quot; <a class="header-anchor" href="#十、linear-walkthroughs——将-经验-变成-理解" aria-label="Permalink to &quot;十、Linear Walkthroughs——将&quot;经验&quot;变成&quot;理解&quot;&quot;">​</a></h2><h3 id="_10-1-认知债务问题" tabindex="-1">10.1 认知债务问题 <a class="header-anchor" href="#_10-1-认知债务问题" aria-label="Permalink to &quot;10.1 认知债务问题&quot;">​</a></h3><p>当 agent 写了代码，而你只是运行它而不理解它——你欠下了<strong>认知债务</strong>（cognitive debt）。</p><p>对于很多简单代码这不是问题，但当你的应用核心变成你不理解的黑箱时：</p><ul><li>无法自信地规划新功能</li><li>无法推理边界情况</li><li>逐渐积累成阻碍速度的技术债务</li></ul><h3 id="_10-2-linear-walkthrough-的价值" tabindex="-1">10.2 Linear Walkthrough 的价值 <a class="header-anchor" href="#_10-2-linear-walkthrough-的价值" aria-label="Permalink to &quot;10.2 Linear Walkthrough 的价值&quot;">​</a></h3><p>让 agent 遍历代码文件，逐行解释代码做什么——这是一个<strong>主动理解代码</strong>的过程。</p><p>Willison 的案例：他用 vibe coding 做了一个 SwiftUI 演示应用，代码全由 Claude Code 生成，他完全没有看代码本身。之后他用 Linear Walkthrough 模式让另一个 agent 帮他梳理代码，&quot;学习&quot; SwiftUI 应用的结构。</p><p><strong>关键发现</strong>：即使是一个 ~40 分钟 vibe coding 的玩具项目，也可以成为探索新生态和学习新技巧的机会。</p><h3 id="_10-3-互动解释-interactive-explanations" tabindex="-1">10.3 互动解释（Interactive Explanations） <a class="header-anchor" href="#_10-3-互动解释-interactive-explanations" aria-label="Permalink to &quot;10.3 互动解释（Interactive Explanations）&quot;">​</a></h3><p>这是 Linear Walkthrough 的扩展——不只是解释代码，而是<strong>构建可交互的动画或工具来解释概念</strong>。</p><p>Willison 的例子：用 Claude Opus 4.6 构建了一个动画来解释词云算法（Archimedean spiral placement）。通过看动画，他真正理解了算法的工作原理，而不只是知道&quot;它用了螺旋布局&quot;这个描述。</p><h2 id="十一、annotated-prompts——值得学习的提示词模板" tabindex="-1">十一、Annotated Prompts——值得学习的提示词模板 <a class="header-anchor" href="#十一、annotated-prompts——值得学习的提示词模板" aria-label="Permalink to &quot;十一、Annotated Prompts——值得学习的提示词模板&quot;">​</a></h2><h3 id="_11-1-artifacts-的正确用法" tabindex="-1">11.1 Artifacts 的正确用法 <a class="header-anchor" href="#_11-1-artifacts-的正确用法" aria-label="Permalink to &quot;11.1 Artifacts 的正确用法&quot;">​</a></h3><p>Willison 用 Claude Artifacts 构建原型和小型 HTML 工具。但他有一个明确偏好：</p><blockquote><p>模型喜欢用 React，但我不喜欢 React 需要的额外构建步骤，所以我用 vanilla JS 构建 artifacts，这样我能轻松复制粘贴代码到其他项目。</p></blockquote><p>这是<strong>工具选择服从于工作流</strong>的典型案例。</p><h3 id="_11-2-proofreader-的边界" tabindex="-1">11.2 Proofreader 的边界 <a class="header-anchor" href="#_11-2-proofreader-的边界" aria-label="Permalink to &quot;11.2 Proofreader 的边界&quot;">​</a></h3><p>Willison 有一条硬线：</p><blockquote><p>任何表达意见或使用&quot;I&quot;的文字，必须是我自己写的。LLM 可以更新代码文档，但如果什么东西要署我的名字，<strong>我亲自写</strong>。</p></blockquote><p>这本质上是一个<strong>责任边界</strong>：机器可以辅助，但不能替代人的声音。</p><h3 id="_11-3-podcast-highlights——复用的艺术" tabindex="-1">11.3 Podcast Highlights——复用的艺术 <a class="header-anchor" href="#_11-3-podcast-highlights——复用的艺术" aria-label="Permalink to &quot;11.3 Podcast Highlights——复用的艺术&quot;">​</a></h3><p>处理播客记录时，Willison 用 LLM 从长 transcript 中提取关键引述。这不是生成内容，而是<strong>从已有内容中提取高价值片段</strong>——与代码复用同一个逻辑。</p><h2 id="十二、系统性总结-agentic-engineering-的核心思维模型" tabindex="-1">十二、系统性总结：Agentic Engineering 的核心思维模型 <a class="header-anchor" href="#十二、系统性总结-agentic-engineering-的核心思维模型" aria-label="Permalink to &quot;十二、系统性总结：Agentic Engineering 的核心思维模型&quot;">​</a></h2><h3 id="_12-1-五个最关键的心智模型" tabindex="-1">12.1 五个最关键的心智模型 <a class="header-anchor" href="#_12-1-五个最关键的心智模型" aria-label="Permalink to &quot;12.1 五个最关键的心智模型&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 代码打字成本趋近于零，但工程判断成本不变</span></span>
<span class="line"><span>2. 测试是默认行为，不是可选项</span></span>
<span class="line"><span>3. 人是质量把关者和架构决策者，agent 是执行放大器</span></span>
<span class="line"><span>4. 每次任务的经验应该被积累，让未来的 agent 更好</span></span>
<span class="line"><span>5. 提交未审查的代码 = 对协作者的不尊重</span></span></code></pre></div><h3 id="_12-2-从-工具使用者-到-系统设计者" tabindex="-1">12.2 从&quot;工具使用者&quot;到&quot;系统设计者&quot; <a class="header-anchor" href="#_12-2-从-工具使用者-到-系统设计者" aria-label="Permalink to &quot;12.2 从&quot;工具使用者&quot;到&quot;系统设计者&quot;&quot;">​</a></h3><p>传统软件工程教育强调&quot;如何正确使用工具&quot;。Agentic Engineering 要求的是：</p><ul><li><strong>理解 LLM 的工作原理</strong>（token、context、reasoning）</li><li><strong>理解工具 harness 的设计</strong>（system prompt、tool calling loop）</li><li><strong>设计有效的反馈机制</strong>（测试、Showboat 记录、手动验证）</li><li><strong>管理信息流</strong>（subagent、context 窗口、缓存策略）</li></ul><p>这是从&quot;用工具做事&quot;到&quot;设计让 AI 工具高效工作的系统&quot;的跃迁。</p><h3 id="_12-3-为什么-simon-willison-的框架值得认真学" tabindex="-1">12.3 为什么 Simon Willison 的框架值得认真学 <a class="header-anchor" href="#_12-3-为什么-simon-willison-的框架值得认真学" aria-label="Permalink to &quot;12.3 为什么 Simon Willison 的框架值得认真学&quot;">​</a></h3><p>最后，我想回到一个更基本的问题：为什么 Willison 的这套指南比大多数 AI 编程资源更有价值？</p><p><strong>答案在于他的方法论立场</strong>：他不只是在讲&quot;怎么用 AI 写代码&quot;，他在讲&quot;在 AI 能写代码的时代，什么是软件工程的本质&quot;。</p><p>他的每一个 pattern，都指向同一个核心问题：</p><blockquote><p><strong>如果机器可以执行常规任务，人应该把精力集中在哪里？</strong></p></blockquote><p>Willison 的答案：</p><ul><li>在判断力和创造力上</li><li>在质量把关和工程标准上</li><li>在理解代码和设计架构上</li><li>在积累经验和传承知识上</li></ul><p>这不是一份&quot;AI 编程入门指南&quot;，而是一份<strong>关于软件工程本质的深度思考</strong>。</p><hr><h2 id="相关资源" tabindex="-1">相关资源 <a class="header-anchor" href="#相关资源" aria-label="Permalink to &quot;相关资源&quot;">​</a></h2><ul><li><a href="https://simonwillison.net/guides/agentic-engineering-patterns/" target="_blank" rel="noreferrer">Simon Willison - Agentic Engineering Patterns（完整指南）</a></li><li><a href="https://simonwillison.net/" target="_blank" rel="noreferrer">Simon Willison 博客</a></li><li><a href="https://til.simonwillison.net/" target="_blank" rel="noreferrer">Simon Willison TIL</a></li><li><a href="https://tools.simonwillison.net/" target="_blank" rel="noreferrer">tools.simonwillison.net</a>（LLM 辅助工具集合）</li><li><a href="https://github.com/simonw/rodney" target="_blank" rel="noreferrer">Rodney - 浏览器自动化工具</a></li><li><a href="https://github.com/simonw/showboat" target="_blank" rel="noreferrer">Showboat - 记录 Agent 工作痕迹</a></li><li><a href="https://every.to/chain-of-thought/compound-engineering-how-every-codes-with-agents" target="_blank" rel="noreferrer">Every - Compound Engineering</a></li></ul>`,205)])])}const k=e(o,[["render",s]]);export{b as __pageData,k as default};
